def curry(func):
    """
    Curries a function with multiple arguments and returns a curried version of the function.
    """

    def curried_func(*args):
        """
        Curried version of the function that takes one argument at a time.
        """
        if len(args) >= func.__code__.co_argcount:
            return func(*args)
        else:
            return lambda arg: curried_func(arg, *args[len(args):func.__code__.co_argcount])

    return curried_func
